Here are the MSTest comparison assertions you should use for boundary checking on `ScoreCalculator`, along with complete test examples:

## Key Comparison Assertions

| Assertion | Purpose |
|---|---|
| `Assert.IsGreaterThan(lowerBound, actual)` | Value exceeds a bound |
| `Assert.IsLessThan(upperBound, actual)` | Value is below a bound |
| `Assert.IsInRange(actual, low, high)` | Value falls within [low, high] |
| `Assert.ThrowsExactly<T>(…)` | Exact exception on invalid input |

## Example Tests

```csharp
using Microsoft.VisualStudio.TestTools.UnitTesting;
using Contoso.Scoring;

[TestClass]
public sealed class ScoreCalculatorTests
{
    private readonly ScoreCalculator _calc = new();

    // ── CalculatePercentage ──

    [TestMethod]
    public void CalculatePercentage_PerfectScore_Returns100()
    {
        var result = _calc.CalculatePercentage(10, 10);
        Assert.AreEqual(100.0, result);
    }

    [TestMethod]
    public void CalculatePercentage_PartialScore_ReturnsInRange()
    {
        var result = _calc.CalculatePercentage(7, 10);
        Assert.IsInRange(result, 0.0, 100.0);
        Assert.AreEqual(70.0, result);
    }

    [TestMethod]
    public void CalculatePercentage_ZeroCorrect_ReturnsZero()
    {
        Assert.AreEqual(0.0, _calc.CalculatePercentage(0, 10));
    }

    [TestMethod]
    public void CalculatePercentage_ZeroTotal_Throws()
    {
        Assert.ThrowsExactly<ArgumentOutOfRangeException>(
            () => _calc.CalculatePercentage(5, 0));
    }

    [TestMethod]
    public void CalculatePercentage_NegativeCorrect_Throws()
    {
        Assert.ThrowsExactly<ArgumentOutOfRangeException>(
            () => _calc.CalculatePercentage(-1, 10));
    }

    [TestMethod]
    public void CalculatePercentage_CorrectExceedsTotal_Throws()
    {
        Assert.ThrowsExactly<ArgumentOutOfRangeException>(
            () => _calc.CalculatePercentage(11, 10));
    }

    // ── GetGrade boundary tests ──

    [TestMethod]
    [DataRow(90.0, "A", DisplayName = "Boundary: exactly 90 → A")]
    [DataRow(89.99, "B", DisplayName = "Boundary: just below 90 → B")]
    [DataRow(80.0, "B", DisplayName = "Boundary: exactly 80 → B")]
    [DataRow(79.99, "C", DisplayName = "Boundary: just below 80 → C")]
    [DataRow(70.0, "C")]
    [DataRow(69.99, "D")]
    [DataRow(60.0, "D")]
    [DataRow(59.99, "F")]
    [DataRow(0.0, "F")]
    [DataRow(100.0, "A")]
    public void GetGrade_AtBoundary_ReturnsExpectedGrade(
        double percentage, string expected)
    {
        Assert.AreEqual(expected, _calc.GetGrade(percentage));
    }

    // ── NormalizeScore ──

    [TestMethod]
    public void NormalizeScore_HalfOfMax_Returns50()
    {
        var result = _calc.NormalizeScore(50, 100);
        Assert.AreEqual(50.0, result);
    }

    [TestMethod]
    public void NormalizeScore_Result_IsAlwaysInRange()
    {
        var result = _calc.NormalizeScore(75, 100);
        Assert.IsInRange(result, 0.0, 100.0);
    }

    [TestMethod]
    public void NormalizeScore_ExceedsMax_ClampedTo100()
    {
        var result = _calc.NormalizeScore(150, 100);
        Assert.AreEqual(100.0, result);
        // Also valid: confirm it doesn't exceed the cap
        Assert.IsLessThan(101.0, result);
    }

    [TestMethod]
    public void NormalizeScore_AboveZero_IsGreaterThanZero()
    {
        Assert.IsGreaterThan(0.0, _calc.NormalizeScore(1, 100));
    }

    [TestMethod]
    public void NormalizeScore_NegativeRaw_Throws()
    {
        Assert.ThrowsExactly<ArgumentOutOfRangeException>(
            () => _calc.NormalizeScore(-1, 100));
    }

    [TestMethod]
    public void NormalizeScore_ZeroMax_Throws()
    {
        Assert.ThrowsExactly<ArgumentOutOfRangeException>(
            () => _calc.NormalizeScore(50, 0));
    }
}
```

## Summary

- **`Assert.IsInRange(actual, low, high)`** — ideal for verifying percentages stay within 0–100
- **`Assert.IsGreaterThan(lowerBound, actual)`** — confirms a value exceeds a threshold
- **`Assert.IsLessThan(upperBound, actual)`** — confirms a value stays below a cap
- **`Assert.ThrowsExactly<T>`** — validates guard clauses throw the exact exception type
- **`[DataRow]` with `DisplayName`** — cleanly tests every grade boundary in one method

These assertions produce far better failure messages than `Assert.IsTrue(x > 0)` — on failure you'll see the actual and boundary values, not just "expected True, got False."
